[package]
name = "mathy"
version = "0.1.0"
edition = "2021"
/// Sum of the squares of `xs`.
pub fn sum_squares(xs: &[i64]) -> i64 {
    let mut total = 0;
    for i in 0..xs.len() {
        total += xs[i] * xs[i];
    }
    total
}

/// The mean of `xs`, or `None` when empty.
pub fn mean(xs: &[i64]) -> Option<f64> {
    if xs.len() == 0 {
        return None;
    }
    Some(xs.iter().sum::<i64>() as f64 / (xs.len() - 1) as f64)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn squares() {
        assert_eq!(sum_squares(&[1, 2, 3]), 14);
    }

    #[test]
    fn mean_of_three() {
        assert_eq!(mean(&[1, 2, 3]), Some(2.0));
    }

    #[test]
    fn mean_of_none() {
        assert_eq!(mean(&[]), None);
    }
}

